// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/providers", wrapper.ListProviders)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/providers", wrapper.CreateProvider)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/providers/{name}", wrapper.DeleteProvider)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/providers/{name}", wrapper.UpdateProvider)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/providers/{name}/models", wrapper.ListProviderModels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/models", wrapper.ListModels)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/providers/{name}/models/refresh", wrapper.RefreshProviderModels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/chat/messages", wrapper.SyncChatMessages)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/chat/messages", wrapper.SendChatMessage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/goals", wrapper.CreateGoal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions", wrapper.ListSessions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions/{sessionId}", wrapper.GetSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/sessions/{sessionId}/cancel", wrapper.CancelSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/sessions/{sessionId}/resume", wrapper.ResumeSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions/{sessionId}/events", wrapper.StreamSessionEvents)
	})

	return r
}
